/* v29: генератор вопросов «Кто? / В каком году? / Расставь по времени» из пула точных фактов.
   Запись пула: who — кто; ask — вопрос «Кто …?»; yq — то же предложение с именем (для вопроса о годе и объяснения);
   ev — короткое название события; year — год; country — страна героя. */
var STORIES_GEN = (function () {
  const rnd = n => Math.floor(Math.random() * n);
  const shuffle = a => { a = a.slice(); for (let i = a.length - 1; i > 0; i--) { const j = rnd(i + 1); const t = a[i]; a[i] = a[j]; a[j] = t; } return a; };
  const pickN = (a, n) => shuffle(a).slice(0, n);
  function pickOrdered(pool, n, gap) {
    for (let tries = 0; tries < 60; tries++) {
      const s = pickN(pool, n).sort((x, y) => x.year - y.year);
      let ok = true;
      for (let i = 1; i < s.length; i++) if (s[i].year - s[i - 1].year < gap) { ok = false; break; }
      if (ok) return s;
    }
    const by = {}; shuffle(pool).forEach(f => { if (!by[f.year]) by[f.year] = f; });
    return pickN(Object.values(by), n).sort((x, y) => x.year - y.year);
  }
  return function make(pool) {
    return function (level) {
      const lv = level >= 3 ? 3 : level <= 1 ? 1 : 2;
      const kinds = lv === 1 ? ['who', 'who', 'what', 'order'] : ['who', 'what', 'year', 'year', 'order'];
      const kind = kinds[rnd(kinds.length)];
      const f = pool[rnd(pool.length)];
      if (kind === 'who') {
        const opts = shuffle([f].concat(pickN(pool.filter(x => x.who !== f.who), lv === 1 ? 2 : 3)));
        return { type: 'one', q: f.ask + '?', a: opts.map(x => x.who), c: opts.indexOf(f), why: f.yq + ' в ' + f.year + ' году (' + f.country + ').' };
      }
      if (kind === 'what') {
        const opts = shuffle([f].concat(pickN(pool.filter(x => x.ev !== f.ev && x.who !== f.who), lv === 1 ? 2 : 3)));
        return { type: 'one', q: 'Какое событие связано с именем: ' + f.who + '?', a: opts.map(x => x.ev), c: opts.indexOf(f), why: f.yq + ' в ' + f.year + ' году.' };
      }
      if (kind === 'year') {
        return { type: 'input', q: 'В каком году ' + f.yq + '?', c: f.year, why: f.yq + ' в ' + f.year + ' году.' };
      }
      const n = lv + 2, s = pickOrdered(pool, n, lv === 1 ? 20 : lv === 2 ? 8 : 1);
      return { type: 'order', q: 'Расставь события по времени — от раннего к позднему.', items: s.map(x => x.ev), why: s.map(x => x.ev + ' — ' + x.year).join(' → ') + '.' };
    };
  };
})();
